#include <bits/stdc++.h>
using namespace std;

// Thread-UNSAFE Singleton (NOT for production!)
class SingletonUnsafe {
private:
    static SingletonUnsafe* instance;
    SingletonUnsafe() { cout << "Singleton created\n"; }

public:
    static SingletonUnsafe* getInstance() {
        if (instance == nullptr) {
            instance = new SingletonUnsafe();
        }
        return instance;
    }

    void doSomething() {
        cout << "Doing something\n";
    }
};

SingletonUnsafe* SingletonUnsafe::instance = nullptr;

// Thread-SAFE Singleton using Meyers' Singleton (C++11+)
class SingletonSafe {
private:
    SingletonSafe() { cout << "Safe Singleton created\n"; }
    ~SingletonSafe() = default;
    SingletonSafe(const SingletonSafe&) = delete;
    SingletonSafe& operator=(const SingletonSafe&) = delete;

public:
    static SingletonSafe& getInstance() {
        static SingletonSafe instance;  // Guaranteed thread-safe in C++11+
        return instance;
    }

    void doSomething() {
        cout << "Safe singleton doing something\n";
    }
};

// Thread-SAFE Singleton using mutex (explicit)
class SingletonMutex {
private:
    static SingletonMutex* instance;
    static mutex mtx;
    SingletonMutex() { cout << "Mutex Singleton created\n"; }

public:
    static SingletonMutex* getInstance() {
        if (instance == nullptr) {  // Double-checked locking
            lock_guard<mutex> lock(mtx);
            if (instance == nullptr) {
                instance = new SingletonMutex();
            }
        }
        return instance;
    }

    void doSomething() {
        cout << "Mutex singleton doing something\n";
    }
};

SingletonMutex* SingletonMutex::instance = nullptr;
mutex SingletonMutex::mtx;

int main() {
    // Meyers' Singleton - Recommended approach
    SingletonSafe& s1 = SingletonSafe::getInstance();
    SingletonSafe& s2 = SingletonSafe::getInstance();

    cout << "Same instance? " << (&s1 == &s2 ? "YES" : "NO") << "\n";
    s1.doSomething();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Interface for testability
class ILogger {
public:
    virtual void log(const string& msg) = 0;
    virtual ~ILogger() = default;
};

class ConsoleLogger : public ILogger {
public:
    void log(const string& msg) override {
        cout << "[LOG] " << msg << "\n";
    }
};

class FileLogger : public ILogger {
    string filename;
public:
    FileLogger(const string& fname) : filename(fname) {}
    void log(const string& msg) override {
        // Write to file
        cout << "[FILE:" << filename << "] " << msg << "\n";
    }
};

// Service Locator - better than raw Singleton
class ServiceLocator {
    static unique_ptr<ILogger> logger;
public:
    static void provide(unique_ptr<ILogger> lg) {
        logger = move(lg);
    }
    static ILogger& getLogger() {
        if (!logger) {
            logger = make_unique<ConsoleLogger>();
        }
        return *logger;
    }
};

unique_ptr<ILogger> ServiceLocator::logger = nullptr;

class Application {
public:
    void run() {
        ServiceLocator::getLogger().log("Application started");
        // Do work
        ServiceLocator::getLogger().log("Application finished");
    }
};

int main() {
    // Inject mock logger for testing, file logger for production
    ServiceLocator::provide(make_unique<FileLogger>("app.log"));

    Application app;
    app.run();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Product Interface
class Button {
public:
    virtual void render() = 0;
    virtual void onClick(function<void()> callback) = 0;
    virtual ~Button() = default;
};

// Concrete Products
class WindowsButton : public Button {
public:
    void render() override {
        cout << "Rendering Windows-style button\n";
    }
    void onClick(function<void()> callback) override {
        cout << "Windows button clicked!\n";
        callback();
    }
};

class MacButton : public Button {
public:
    void render() override {
        cout << "Rendering Mac-style button\n";
    }
    void onClick(function<void()> callback) override {
        cout << "Mac button clicked!\n";
        callback();
    }
};

class LinuxButton : public Button {
public:
    void render() override {
        cout << "Rendering Linux-style button\n";
    }
    void onClick(function<void()> callback) override {
        cout << "Linux button clicked!\n";
        callback();
    }
};

// Creator (Abstract Class)
class Dialog {
public:
    virtual ~Dialog() = default;

    // Factory Method
    virtual unique_ptr<Button> createButton() = 0;

    void render() {
        auto button = createButton();
        button->render();
        button->onClick([]() { cout << "Dialog closed!\n"; });
    }
};

// Concrete Creators
class WindowsDialog : public Dialog {
public:
    unique_ptr<Button> createButton() override {
        return make_unique<WindowsButton>();
    }
};

class MacDialog : public Dialog {
public:
    unique_ptr<Button> createButton() override {
        return make_unique<MacButton>();
    }
};

class LinuxDialog : public Dialog {
public:
    unique_ptr<Button> createButton() override {
        return make_unique<LinuxButton>();
    }
};

// Application that works with any dialog
class Application {
    unique_ptr<Dialog> dialog;
public:
    Application(unique_ptr<Dialog> dlg) : dialog(move(dlg)) {}

    void run() {
        dialog->render();
    }
};

int main() {
    string os;
    cout << "Enter OS (windows/mac/linux): ";
    cin >> os;

    unique_ptr<Dialog> dialog;
    if (os == "windows") dialog = make_unique<WindowsDialog>();
    else if (os == "mac") dialog = make_unique<MacDialog>();
    else dialog = make_unique<LinuxDialog>();

    Application app(move(dialog));
    app.run();

    return 0;
}

