// BAD: Telescoping constructors
class PizzaBad {
    string size;
    bool cheese;
    bool pepperoni;
    bool mushrooms;
    bool onions;
    string crustType;

public:
    // Constructor explosion!
    PizzaBad(string s) : size(s), cheese(false), pepperoni(false), mushrooms(false), onions(false), crustType("regular") {}
    PizzaBad(string s, bool c) : size(s), cheese(c), pepperoni(false), mushrooms(false), onions(false), crustType("regular") {}
    PizzaBad(string s, bool c, bool p) : size(s), cheese(c), pepperoni(p), mushrooms(false), onions(false), crustType("regular") {}
    PizzaBad(string s, bool c, bool p, bool m) : size(s), cheese(c), pepperoni(p), mushrooms(m), onions(false), crustType("regular") {}
    // ... and so on, exponentially many combinations!
};

// GOOD: Builder Pattern
class Pizza {
    string size;
    bool cheese = false;
    bool pepperoni = false;
    bool mushrooms = false;
    bool onions = false;
    string crustType = "regular";
    vector<string> extraToppings;

    // Private constructor - only Builder can create
    Pizza() = default;

public:
    class Builder {
        Pizza* pizza;
    public:
        Builder() { pizza = new Pizza(); }

        Builder& setSize(const string& s) {
            pizza->size = s;
            return *this;
        }
        Builder& addCheese() {
            pizza->cheese = true;
            return *this;
        }
        Builder& addPepperoni() {
            pizza->pepperoni = true;
            return *this;
        }
        Builder& addMushrooms() {
            pizza->mushrooms = true;
            return *this;
        }
        Builder& addOnions() {
            pizza->onions = true;
            return *this;
        }
        Builder& setCrust(const string& c) {
            pizza->crustType = c;
            return *this;
        }
        Builder& addTopping(const string& t) {
            pizza->extraToppings.push_back(t);
            return *this;
        }

        Pizza* build() {
            if (pizza->size.empty()) {
                throw runtime_error("Size is required!");
            }
            Pizza* result = pizza;
            pizza = nullptr;  // Transfer ownership
            return result;
        }

        ~Builder() { delete pizza; }
    };

    void describe() const {
        cout << "Pizza: " << size << "\n";
        cout << "  Crust: " << crustType << "\n";
        cout << "  Cheese: " << (cheese ? "yes" : "no") << "\n";
        cout << "  Pepperoni: " << (pepperoni ? "yes" : "no") << "\n";
        cout << "  Mushrooms: " << (mushrooms ? "yes" : "no") << "\n";
        cout << "  Onions: " << (onions ? "yes" : "no") << "\n";
        cout << "  Extras: ";
        for (auto& t : extraToppings) cout << t << " ";
        cout << "\n";
    }

    ~Pizza() = default;
};

int main() {
    // Fluent interface - readable and flexible!
    Pizza* myPizza = Pizza::Builder()
        .setSize("Large")
        .setCrust("Thin")
        .addCheese()
        .addPepperoni()
        .addMushrooms()
        .addTopping("Olives")
        .addTopping("Jalapenos")
        .build();

    myPizza->describe();
    delete myPizza;

    // Another pizza with different configuration
    Pizza* veggiePizza = Pizza::Builder()
        .setSize("Medium")
        .setCrust("Whole Wheat")
        .addCheese()
        .addMushrooms()
        .addOnions()
        .addTopping("Spinach")
        .build();

    veggiePizza->describe();
    delete veggiePizza;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Product
class House {
public:
    string walls;
    string roof;
    string doors;
    string windows;
    bool hasGarage = false;
    bool hasPool = false;
    bool hasGarden = false;

    void describe() const {
        cout << "House with " << walls << " walls, " << roof << " roof\n";
        cout << "  Doors: " << doors << ", Windows: " << windows << "\n";
        if (hasGarage) cout << "  Has garage\n";
        if (hasPool) cout << "  Has swimming pool\n";
        if (hasGarden) cout << "  Has garden\n";
    }
};

// Abstract Builder
class HouseBuilder {
public:
    virtual ~HouseBuilder() = default;
    virtual void buildWalls() = 0;
    virtual void buildRoof() = 0;
    virtual void buildDoors() = 0;
    virtual void buildWindows() = 0;
    virtual void buildGarage() {}
    virtual void buildPool() {}
    virtual void buildGarden() {}
    virtual House* getResult() = 0;
};

// Concrete Builder: Wooden House
class WoodenHouseBuilder : public HouseBuilder {
    House* house;
public:
    WoodenHouseBuilder() { house = new House(); }
    void buildWalls() override { house->walls = "Wooden"; }
    void buildRoof() override { house->roof = "Wooden shingle"; }
    void buildDoors() override { house->doors = "Wooden"; }
    void buildWindows() override { house->windows = "Wooden frame"; }
    void buildGarage() override { house->hasGarage = true; }
    void buildGarden() override { house->hasGarden = true; }
    House* getResult() override { return house; }
};

// Concrete Builder: Stone House
class StoneHouseBuilder : public HouseBuilder {
    House* house;
public:
    StoneHouseBuilder() { house = new House(); }
    void buildWalls() override { house->walls = "Stone"; }
    void buildRoof() override { house->roof = "Tile"; }
    void buildDoors() override { house->doors = "Iron"; }
    void buildWindows() override { house->windows = "Reinforced glass"; }
    void buildPool() override { house->hasPool = true; }
    House* getResult() override { return house; }
};

// Director - knows the construction steps
class ConstructionDirector {
public:
    void constructBasicHouse(HouseBuilder& builder) {
        builder.buildWalls();
        builder.buildRoof();
        builder.buildDoors();
        builder.buildWindows();
    }

    void constructLuxuryHouse(HouseBuilder& builder) {
        constructBasicHouse(builder);
        builder.buildGarage();
        builder.buildPool();
        builder.buildGarden();
    }
};

int main() {
    ConstructionDirector director;

    // Build basic wooden house
    WoodenHouseBuilder woodBuilder;
    director.constructBasicHouse(woodBuilder);
    House* woodHouse = woodBuilder.getResult();
    cout << "=== Wooden House ===\n";
    woodHouse->describe();

    // Build luxury stone house
    StoneHouseBuilder stoneBuilder;
    director.constructLuxuryHouse(stoneBuilder);
    House* stoneHouse = stoneBuilder.getResult();
    cout << "\n=== Stone House ===\n";
    stoneHouse->describe();

    delete woodHouse;
    delete stoneHouse;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Modern approach using optional and move semantics
class Config {
    string host;
    int port = 8080;
    int timeout = 30;
    bool ssl = false;
    vector<string> headers;

    Config() = default;

public:
    class Builder {
        Config config;
    public:
        Builder& host(string h) { config.host = move(h); return *this; }
        Builder& port(int p) { config.port = p; return *this; }
        Builder& timeout(int t) { config.timeout = t; return *this; }
        Builder& enableSSL() { config.ssl = true; return *this; }
        Builder& addHeader(string h) { 
            config.headers.push_back(move(h)); 
            return *this; 
        }

        Config build() && {
            if (config.host.empty()) throw runtime_error("Host required");
            return move(config);
        }
    };

    void print() const {
        cout << "Config: " << host << ":" << port << "\n";
        cout << "  Timeout: " << timeout << "s\n";
        cout << "  SSL: " << (ssl ? "enabled" : "disabled") << "\n";
        cout << "  Headers: ";
        for (auto& h : headers) cout << h << " ";
        cout << "\n";
    }

    friend class Builder;
};

int main() {
    Config cfg = Config::Builder()
        .host("api.example.com")
        .port(443)
        .enableSSL()
        .timeout(60)
        .addHeader("Authorization: Bearer token")
        .addHeader("Content-Type: application/json")
        .build();

    cfg.print();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Prototype Interface
class Document {
public:
    virtual ~Document() = default;
    virtual unique_ptr<Document> clone() const = 0;
    virtual void print() const = 0;
    virtual void setContent(const string& content) = 0;
};

// Concrete Prototype: Report
class Report : public Document {
    string title;
    string content;
    vector<string> sections;

public:
    Report(const string& t) : title(t) {}

    // Copy constructor for deep copy
    Report(const Report& other) 
        : title(other.title), 
          content(other.content),
          sections(other.sections) {}  // vector deep copies automatically

    unique_ptr<Document> clone() const override {
        return make_unique<Report>(*this);  // Uses copy constructor
    }

    void setContent(const string& c) override {
        content = c;
    }

    void addSection(const string& section) {
        sections.push_back(section);
    }

    void print() const override {
        cout << "=== Report: " << title << " ===\n";
        cout << "Content: " << content << "\n";
        cout << "Sections:\n";
        for (auto& s : sections) cout << "  - " << s << "\n";
    }
};

// Concrete Prototype: Presentation
class Presentation : public Document {
    string theme;
    vector<string> slides;
    int slideCount = 0;

public:
    Presentation(const string& t) : theme(t) {}

    Presentation(const Presentation& other)
        : theme(other.theme),
          slides(other.slides),
          slideCount(other.slideCount) {}

    unique_ptr<Document> clone() const override {
        return make_unique<Presentation>(*this);
    }

    void setContent(const string& c) override {
        // For presentation, content is the theme description
        theme += " - " + c;
    }

    void addSlide(const string& slide) {
        slides.push_back(slide);
        slideCount++;
    }

    void print() const override {
        cout << "=== Presentation: " << theme << " ===\n";
        cout << "Slides (" << slideCount << "):\n";
        for (auto& s : slides) cout << "  [Slide] " << s << "\n";
    }
};

// Prototype Registry - manages available prototypes
class DocumentRegistry {
    unordered_map<string, unique_ptr<Document>> prototypes;

public:
    void registerPrototype(const string& name, unique_ptr<Document> doc) {
        prototypes[name] = move(doc);
    }

    unique_ptr<Document> create(const string& name) {
        if (prototypes.find(name) == prototypes.end()) {
            throw runtime_error("Unknown prototype: " + name);
        }
        return prototypes[name]->clone();
    }
};

int main() {
    DocumentRegistry registry;

    // Register prototypes
    auto reportProto = make_unique<Report>("Monthly Report");
    reportProto->addSection("Executive Summary");
    reportProto->addSection("Financial Data");
    registry.registerPrototype("report", move(reportProto));

    auto presProto = make_unique<Presentation>("Corporate");
    presProto->addSlide("Title Slide");
    presProto->addSlide("Agenda");
    registry.registerPrototype("presentation", move(presProto));

    // Create documents from prototypes
    auto doc1 = registry.create("report");
    doc1->setContent("Q4 2024 Results");
    doc1->print();

    cout << "\n";

    auto doc2 = registry.create("presentation");
    doc2->setContent("Annual Meeting");
    doc2->print();

    cout << "\n";

    // Clone and modify independently
    auto doc3 = registry.create("report");
    doc3->setContent("Q1 2025 Forecast");
    doc3->print();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Complex object with nested structures
class Shape {
protected:
    string color;
    int x, y;
    vector<pair<int,int>> points;  // Polygon points

public:
    Shape(const string& c, int xPos, int yPos) 
        : color(c), x(xPos), y(yPos) {}

    virtual ~Shape() = default;
    virtual unique_ptr<Shape> clone() const = 0;

    void move(int dx, int dy) { x += dx; y += dy; }
    void setColor(const string& c) { color = c; }
    void addPoint(int px, int py) { points.push_back({px, py}); }

    void describe() const {
        cout << "Shape at (" << x << "," << y << ") color: " << color << "\n";
        cout << "  Points: ";
        for (auto& p : points) cout << "(" << p.first << "," << p.second << ") ";
        cout << "\n";
    }
};

class Circle : public Shape {
    double radius;
public:
    Circle(const string& c, int x, int y, double r) 
        : Shape(c, x, y), radius(r) {}

    // Deep copy constructor
    Circle(const Circle& other) 
        : Shape(other), radius(other.radius) {}

    unique_ptr<Shape> clone() const override {
        return make_unique<Circle>(*this);
    }

    void setRadius(double r) { radius = r; }
    void describe() const {
        Shape::describe();
        cout << "  Radius: " << radius << "\n";
    }
};

class Rectangle : public Shape {
    double width, height;
public:
    Rectangle(const string& c, int x, int y, double w, double h)
        : Shape(c, x, y), width(w), height(h) {}

    Rectangle(const Rectangle& other)
        : Shape(other), width(other.width), height(other.height) {}

    unique_ptr<Shape> clone() const override {
        return make_unique<Rectangle>(*this);
    }

    void setDimensions(double w, double h) { width = w; height = h; }
    void describe() const {
        Shape::describe();
        cout << "  Width: " << width << ", Height: " << height << "\n";
    }
};

int main() {
    // Create original shapes
    Circle original("Red", 10, 20, 5.0);
    original.addPoint(10, 20);
    original.addPoint(15, 20);

    // Clone and modify independently
    auto clone1 = original.clone();
    clone1->move(100, 100);
    clone1->setColor("Blue");

    auto clone2 = original.clone();
    clone2->setColor("Green");

    cout << "Original:\n";
    original.describe();

    cout << "\nClone 1 (moved, recolored):\n";
    clone1->describe();

    cout << "\nClone 2 (recolored):\n";
    clone2->describe();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Target Interface (what the client expects)
class MediaPlayer {
public:
    virtual ~MediaPlayer() = default;
    virtual void play(const string& filename) = 0;
};

// Adaptee 1: Advanced media player with different interface
class AdvancedMediaPlayer {
public:
    virtual ~AdvancedMediaPlayer() = default;
    virtual void playVlc(const string& filename) = 0;
    virtual void playMp4(const string& filename) = 0;
};

class VlcPlayer : public AdvancedMediaPlayer {
public:
    void playVlc(const string& filename) override {
        cout << "Playing vlc file: " << filename << "\n";
    }
    void playMp4(const string& filename) override {
        // VLC doesn't support MP4
    }
};

class Mp4Player : public AdvancedMediaPlayer {
public:
    void playVlc(const string& filename) override {
        // MP4 player doesn't support VLC
    }
    void playMp4(const string& filename) override {
        cout << "Playing mp4 file: " << filename << "\n";
    }
};

// Adapter: Makes AdvancedMediaPlayer compatible with MediaPlayer
class MediaAdapter : public MediaPlayer {
    unique_ptr<AdvancedMediaPlayer> advancedPlayer;
    string audioType;

public:
    MediaAdapter(const string& type) : audioType(type) {
        if (type == "vlc") {
            advancedPlayer = make_unique<VlcPlayer>();
        } else if (type == "mp4") {
            advancedPlayer = make_unique<Mp4Player>();
        }
    }

    void play(const string& filename) override {
        if (audioType == "vlc") {
            advancedPlayer->playVlc(filename);
        } else if (audioType == "mp4") {
            advancedPlayer->playMp4(filename);
        }
    }
};

// Client class that uses the target interface
class AudioPlayer : public MediaPlayer {
    unique_ptr<MediaAdapter> adapter;

public:
    void play(const string& filename) override {
        // Extract file extension
        size_t dotPos = filename.rfind('.');
        string ext = (dotPos != string::npos) ? filename.substr(dotPos + 1) : "";

        // Built-in support
        if (ext == "mp3") {
            cout << "Playing mp3 file: " << filename << "\n";
        } 
        // Use adapter for advanced formats
        else if (ext == "vlc" || ext == "mp4") {
            adapter = make_unique<MediaAdapter>(ext);
            adapter->play(filename);
        } 
        else {
            cout << "Invalid media. " << ext << " format not supported\n";
        }
    }
};

int main() {
    AudioPlayer player;

    player.play("song.mp3");
    player.play("movie.mp4");
    player.play("video.vlc");
    player.play("document.pdf");

    return 0;
}

