// Legacy system - cannot be modified
class LegacyPrinter {
public:
    void oldPrint(const char* text) {
        cout << "Legacy Printer: " << text << "\n";
    }
};

class LegacyScanner {
public:
    char* oldScan() {
        static char buffer[256];
        strcpy(buffer, "Scanned data from legacy");
        return buffer;
    }
};

// Modern interface
class ModernPrinter {
public:
    virtual ~ModernPrinter() = default;
    virtual void print(const string& text) = 0;
};

class ModernScanner {
public:
    virtual ~ModernScanner() = default;
    virtual string scan() = 0;
};

// Adapters
class PrinterAdapter : public ModernPrinter {
    LegacyPrinter* legacy;
public:
    PrinterAdapter(LegacyPrinter* lp) : legacy(lp) {}
    void print(const string& text) override {
        legacy->oldPrint(text.c_str());
    }
};

class ScannerAdapter : public ModernScanner {
    LegacyScanner* legacy;
public:
    ScannerAdapter(LegacyScanner* ls) : legacy(ls) {}
    string scan() override {
        return string(legacy->oldScan());
    }
};

// Modern multifunction device using adapters
class MultifunctionDevice : public ModernPrinter, public ModernScanner {
    unique_ptr<PrinterAdapter> printerAdapter;
    unique_ptr<ScannerAdapter> scannerAdapter;

public:
    MultifunctionDevice(LegacyPrinter* p, LegacyScanner* s) 
        : printerAdapter(make_unique<PrinterAdapter>(p)),
          scannerAdapter(make_unique<ScannerAdapter>(s)) {}

    void print(const string& text) override {
        printerAdapter->print(text);
    }

    string scan() override {
        return scannerAdapter->scan();
    }

    void copy() {
        string data = scan();
        print(data);
    }
};

int main() {
    LegacyPrinter oldPrinter;
    LegacyScanner oldScanner;

    MultifunctionDevice mfd(&oldPrinter, &oldScanner);

    mfd.print("Hello World");
    string scanned = mfd.scan();
    cout << "Scanned: " << scanned << "\n";

    cout << "Copy operation:\n";
    mfd.copy();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Custom stack adapter using vector
template<typename T>
class StackAdapter {
    vector<T> data;
public:
    void push(const T& item) { data.push_back(item); }
    void pop() { 
        if (!data.empty()) data.pop_back(); 
    }
    T& top() { return data.back(); }
    bool empty() const { return data.empty(); }
    size_t size() const { return data.size(); }
};

// Queue adapter using deque
template<typename T>
class QueueAdapter {
    deque<T> data;
public:
    void enqueue(const T& item) { data.push_back(item); }
    void dequeue() { 
        if (!data.empty()) data.pop_front(); 
    }
    T& front() { return data.front(); }
    bool empty() const { return data.empty(); }
    size_t size() const { return data.size(); }
};

int main() {
    StackAdapter<int> stack;
    stack.push(10);
    stack.push(20);
    stack.push(30);

    cout << "Stack (LIFO): ";
    while (!stack.empty()) {
        cout << stack.top() << " ";
        stack.pop();
    }
    cout << "\n";

    QueueAdapter<int> queue;
    queue.enqueue(10);
    queue.enqueue(20);
    queue.enqueue(30);

    cout << "Queue (FIFO): ";
    while (!queue.empty()) {
        cout << queue.front() << " ";
        queue.dequeue();
    }
    cout << "\n";

    return 0;
}

