        : amp(a), tuner(t), dvd(d), projector(p), lights(l), screen(s), popper(pp) {}

    void watchMovie(const string& movie) {
        cout << "\n=== Get ready to watch \"" << movie << "\" ===\n";
        popper.on();
        popper.pop();
        lights.dim(10);
        screen.down();
        projector.on();
        projector.wideScreenMode();
        amp.on();
        amp.setSource("DVD");
        amp.setVolume(5);
        dvd.on();
        dvd.play(movie);
    }

    void endMovie() {
        cout << "\n=== Shutting down theater ===\n";
        popper.off();
        lights.on();
        screen.up();
        projector.off();
        amp.off();
        dvd.stop();
        dvd.eject();
        dvd.off();
    }

    void listenToRadio(double frequency) {
        cout << "\n=== Tuning in to radio ===\n";
        lights.on();
        amp.on();
        amp.setSource("Tuner");
        amp.setVolume(5);
        tuner.on();
        tuner.setFrequency(frequency);
    }
};

int main() {
    // Create subsystem components
    Amplifier amp;
    Tuner tuner;
    DVDPlayer dvd;
    Projector projector;
    TheaterLights lights;
    Screen screen;
    PopcornPopper popper;

    // Create facade
    HomeTheaterFacade theater(amp, tuner, dvd, projector, lights, screen, popper);

    // Simple one-method calls instead of complex sequences
    theater.watchMovie("Inception");
    theater.endMovie();

    theater.listenToRadio(101.5);

    return 0;
}

