public:
    void begin() { inTransaction = true; cout << "Transaction started\n"; }
    void commit() { inTransaction = false; cout << "Transaction committed\n"; }
    void rollback() { inTransaction = false; cout << "Transaction rolled back\n"; }
};

// Database Facade
class DatabaseFacade {
