    virtual void read() const = 0;
    virtual void write(const string& content) = 0;
    virtual void deleteDoc() = 0;
    virtual string getInfo() const = 0;
};

// Real Subject
class RealDocument : public Document {
    string content;
    string filename;

public:
    RealDocument(const string& f, const string& c = "") : filename(f), content(c) {}

    void read() const override {
        cout << "Reading " << filename << ": " << content << "\n";
    }

    void write(const string& c) override {
        content = c;
        cout << "Writing to " << filename << "\n";
    }

    void deleteDoc() override {
        cout << "Deleting " << filename << "\n";
    }

    string getInfo() const override {
        return filename + " (" + to_string(content.size()) + " bytes)";
    }
};

enum class Permission { NONE, READ, WRITE, ADMIN };

// Protection Proxy
class DocumentProxy : public Document {
    unique_ptr<RealDocument> realDoc;
    string filename;
    Permission userPermission;
    string currentUser;

    bool checkPermission(Permission required) const {
        return static_cast<int>(userPermission) >= static_cast<int>(required);
    }

    void ensureLoaded() {
        if (!realDoc) {
            realDoc = make_unique<RealDocument>(filename);
        }
    }

public:
    DocumentProxy(const string& f, const string& user, Permission perm)
        : filename(f), currentUser(user), userPermission(perm) {}

    void read() const override {
        if (!checkPermission(Permission::READ)) {
            cout << "ACCESS DENIED: " << currentUser << " cannot read " << filename << "\n";
            return;
        }
        // Note: read is const, so we use a mutable approach or load in constructor
        cout << currentUser << " reads " << filename << "\n";
    }

    void write(const string& content) override {
        if (!checkPermission(Permission::WRITE)) {
            cout << "ACCESS DENIED: " << currentUser << " cannot write to " << filename << "\n";
            return;
        }
        ensureLoaded();
        realDoc->write(content);
    }

    void deleteDoc() override {
        if (!checkPermission(Permission::ADMIN)) {
            cout << "ACCESS DENIED: " << currentUser << " cannot delete " << filename << "\n";
            return;
        }
        ensureLoaded();
        realDoc->deleteDoc();
    }

    string getInfo() const override {
        return filename + " [Access: " + to_string(static_cast<int>(userPermission)) + "]";
    }
};

class DocumentManager {
    unordered_map<string, unique_ptr<Document>> documents;

public:
    void addDocument(const string& name, const string& user, Permission perm) {
        documents[name] = make_unique<DocumentProxy>(name, user, perm);
    }

    Document* getDocument(const string& name) {
        if (documents.find(name) != documents.end()) {
            return documents[name].get();
        }
        return nullptr;
    }
};

int main() {
    DocumentManager manager;

    // Different users with different permissions
    manager.addDocument("secret.txt", "Alice", Permission::ADMIN);
    manager.addDocument("secret.txt", "Bob", Permission::READ);
    manager.addDocument("secret.txt", "Charlie", Permission::WRITE);
    manager.addDocument("secret.txt", "Dave", Permission::NONE);

    cout << "=== Alice (ADMIN) ===\n";
    auto aliceDoc = manager.getDocument("secret.txt");
    aliceDoc->read();
    aliceDoc->write("Top secret data");
    aliceDoc->deleteDoc();

    cout << "\n=== Bob (READ) ===\n";
    auto bobDoc = manager.getDocument("secret.txt");
    bobDoc->read();
    bobDoc->write("Hacked!");
    bobDoc->deleteDoc();

    cout << "\n=== Dave (NONE) ===\n";
    auto daveDoc = manager.getDocument("secret.txt");
    daveDoc->read();

    return 0;
}

