// Request structure
class SupportTicket {
public:
    enum class Level { BASIC, INTERMEDIATE, ADVANCED, CRITICAL };
    string description;
    Level level;
    string customer;

    SupportTicket(const string& desc, Level lvl, const string& cust)
        : description(desc), level(lvl), customer(cust) {}
};

// Handler Interface
class SupportHandler {
protected:
    unique_ptr<SupportHandler> nextHandler;
    SupportTicket::Level handledLevel;
    string handlerName;

public:
    SupportHandler(const string& name, SupportTicket::Level lvl)
        : handlerName(name), handledLevel(lvl) {}

    virtual ~SupportHandler() = default;

    void setNext(unique_ptr<SupportHandler> handler) {
        nextHandler = move(handler);
    }

    void handle(SupportTicket& ticket) {
        if (canHandle(ticket)) {
            process(ticket);
        } else if (nextHandler) {
            cout << handlerName << " escalates to next level\n";
            nextHandler->handle(ticket);
        } else {
            cout << "No handler available for ticket: " << ticket.description << "\n";
        }
    }

    virtual bool canHandle(const SupportTicket& ticket) {
        return ticket.level == handledLevel;
    }

    virtual void process(SupportTicket& ticket) = 0;
};

// Concrete Handlers
class BasicSupport : public SupportHandler {
public:
    BasicSupport() : SupportHandler("Basic Support", SupportTicket::Level::BASIC) {}

    void process(SupportTicket& ticket) override {
        cout << "[Basic Support] Handling: " << ticket.description 
             << " for " << ticket.customer << "\n";
        cout << "  -> Solution: Restart device, check connections\n";
    }
};

class TechnicalSupport : public SupportHandler {
public:
    TechnicalSupport() : SupportHandler("Technical Support", SupportTicket::Level::INTERMEDIATE) {}

    void process(SupportTicket& ticket) override {
        cout << "[Technical Support] Handling: " << ticket.description 
             << " for " << ticket.customer << "\n";
        cout << "  -> Solution: Update drivers, run diagnostics\n";
    }
};

class SeniorEngineer : public SupportHandler {
public:
    SeniorEngineer() : SupportHandler("Senior Engineer", SupportTicket::Level::ADVANCED) {}

    void process(SupportTicket& ticket) override {
        cout << "[Senior Engineer] Handling: " << ticket.description 
             << " for " << ticket.customer << "\n";
        cout << "  -> Solution: Code review, system architecture analysis\n";
    }
};

class Manager : public SupportHandler {
public:
    Manager() : SupportHandler("Manager", SupportTicket::Level::CRITICAL) {}

    void process(SupportTicket& ticket) override {
        cout << "[Manager] CRITICAL ISSUE: " << ticket.description 
             << " for " << ticket.customer << "\n";
        cout << "  -> Solution: Emergency response team deployed, customer compensation authorized\n";
    }
};

// Builder for chain construction
class SupportChainBuilder {
    unique_ptr<SupportHandler> head;
    SupportHandler* tail = nullptr;

public:
    SupportChainBuilder& add(unique_ptr<SupportHandler> handler) {
        if (!head) {
            head = move(handler);
            tail = head.get();
        } else {
            tail->setNext(move(handler));
            tail = tail->nextHandler.get();
        }
        return *this;
    }

    unique_ptr<SupportHandler> build() {
        return move(head);
    }
};

int main() {
    // Build chain: Basic -> Technical -> Senior -> Manager
    auto chain = SupportChainBuilder()
        .add(make_unique<BasicSupport>())
        .add(make_unique<TechnicalSupport>())
        .add(make_unique<SeniorEngineer>())
        .add(make_unique<Manager>())
        .build();

    vector<SupportTicket> tickets = {
        {"Forgot password", SupportTicket::Level::BASIC, "Alice"},
        {"Blue screen error", SupportTicket::Level::INTERMEDIATE, "Bob"},
        {"Database corruption", SupportTicket::Level::ADVANCED, "Charlie"},
        {"Security breach", SupportTicket::Level::CRITICAL, "Dave"},
    };

    for (auto& ticket : tickets) {
        cout << "\n=== Ticket: " << ticket.description << " ===\n";
        chain->handle(ticket);
    }

    return 0;
}

