        if (req.amount <= approvalLimit) {
            approve(req);
        } else if (next) {
            cout << name << " cannot approve $" << req.amount 
                 << " (limit: $" << approvalLimit << "), forwarding...\n";
            next->processRequest(req);
        } else {
            cout << "Request $" << req.amount << " DENIED - exceeds all approval limits\n";
        }
    }

    virtual void approve(const PurchaseRequest& req) {
        cout << name << " APPROVED request #" << req.id 
             << " for $" << req.amount << " (" << req.purpose << ")\n";
    }
};

class Director : public Approver {
public:
    Director() : Approver("Director", 10000) {}
};

class VP : public Approver {
public:
    VP() : Approver("Vice President", 50000) {}
};

class CFO : public Approver {
public:
    CFO() : Approver("CFO", 100000) {}
};

class CEO : public Approver {
public:
    CEO() : Approver("CEO", 500000) {}
    void approve(const PurchaseRequest& req) override {
        cout << "CEO APPROVED request #" << req.id 
             << " for $" << req.amount << " (" << req.purpose << ")\n";
        cout << "  -> Executive board notification sent\n";
    }
};

int main() {
    auto director = make_shared<Director>();
    auto vp = make_shared<VP>();
    auto cfo = make_shared<CFO>();
    auto ceo = make_shared<CEO>();

    director->setNext(vp);
    vp->setNext(cfo);
    cfo->setNext(ceo);

    vector<PurchaseRequest> requests = {
        {101, 5000, "Office supplies"},
        {102, 25000, "New workstations"},
        {102, 75000, "Server upgrade"},
        {103, 200000, "Office renovation"},
        {104, 600000, "Acquisition proposal"},
    };

    for (const auto& req : requests) {
        cout << "\n=== Request #" << req.id << " : $" << req.amount << " ===\n";
        director->processRequest(req);
    }

    return 0;
}

