// Receiver
class DrawingCanvas {
    vector<string> shapes;

public:
    void addShape(const string& shape) {
        shapes.push_back(shape);
    }

    void removeLastShape() {
        if (!shapes.empty()) shapes.pop_back();
    }

    void clear() { shapes.clear(); }

    void display() const {
        cout << "Canvas: ";
        for (const auto& s : shapes) cout << "[" << s << "] ";
        if (shapes.empty()) cout << "(empty)";
        cout << "\n";
    }

    size_t getShapeCount() const { return shapes.size(); }
};

// Command Interface
class DrawCommand {
public:
    virtual ~DrawCommand() = default;
    virtual void execute() = 0;
    virtual void undo() = 0;
    virtual unique_ptr<DrawCommand> clone() const = 0;
};

class AddShapeCommand : public DrawCommand {
    DrawingCanvas& canvas;
    string shape;

public:
    AddShapeCommand(DrawingCanvas& c, const string& s) : canvas(c), shape(s) {}

    void execute() override { canvas.addShape(shape); }
    void undo() override { canvas.removeLastShape(); }

    unique_ptr<DrawCommand> clone() const override {
        return make_unique<AddShapeCommand>(canvas, shape);
    }
};

// Macro: Composite Command
class MacroCommand : public DrawCommand {
    vector<unique_ptr<DrawCommand>> commands;

public:
    void addCommand(unique_ptr<DrawCommand> cmd) {
        commands.push_back(move(cmd));
    }

    void execute() override {
        for (auto& cmd : commands) {
            cmd->execute();
        }
    }

    void undo() override {
        // Undo in reverse order
        for (auto it = commands.rbegin(); it != commands.rend(); ++it) {
            (*it)->undo();
        }
    }

    unique_ptr<DrawCommand> clone() const override {
        auto macro = make_unique<MacroCommand>();
        for (const auto& cmd : commands) {
            macro->addCommand(cmd->clone());
        }
        return macro;
    }

    size_t size() const { return commands.size(); }
};

// Macro Recorder
class MacroRecorder {
    DrawingCanvas& canvas;
    unique_ptr<MacroCommand> recording;
    bool isRecording = false;
    vector<unique_ptr<MacroCommand>> savedMacros;

public:
    MacroRecorder(DrawingCanvas& c) : canvas(c) {}

    void startRecording() {
        recording = make_unique<MacroCommand>();
        isRecording = true;
        cout << "Recording started...\n";
    }

    void recordAction(const string& shape) {
        if (isRecording) {
            recording->addCommand(make_unique<AddShapeCommand>(canvas, shape));
        }
    }

    void stopRecording(const string& name) {
        if (isRecording && recording->size() > 0) {
            savedMacros.push_back(move(recording));
            cout << "Macro '" << name << "' saved with " 
                 << savedMacros.back()->size() << " commands\n";
        }
        isRecording = false;
    }

    void playMacro(size_t index) {
        if (index < savedMacros.size()) {
            cout << "Playing macro...\n";
            savedMacros[index]->execute();
        }
    }

    void listMacros() const {
        cout << "Saved macros: " << savedMacros.size() << "\n";
    }
};

int main() {
    DrawingCanvas canvas;
    MacroRecorder recorder(canvas);

    // Record a macro
    recorder.startRecording();
    recorder.recordAction("Circle");
    recorder.recordAction("Rectangle");
    recorder.recordAction("Triangle");
    recorder.stopRecording("Basic Shapes");

    canvas.display();  // Shows recorded shapes

    canvas.clear();
    cout << "\nCanvas cleared.\n";

    // Play the macro
    recorder.playMacro(0);
    canvas.display();

    return 0;
}

